    #[cfg(not(target_os = "macos"))]
    #[test]
    fn wrap_is_passthrough_off_macos() {
        let policy = SandboxPolicy::deny("/proj".into());
        let cmd = wrap(&policy, "/bin/echo", &["hi".to_string()], std::path::Path::new("/proj"));
        assert_eq!(cmd.program, "/bin/echo");
